#!/bin/sh
# Derived from kinsamanka/OpenStick-Builder (MIT). sha256 verification kept.
# The GPT is generated by scripts/gen-gpt.sh (real eMMC size from boards/<BOARD>/board.env).

set -eu
cd "$(dirname "$0")/.."
SRC="https://archive.org/download/dragonboard-410c-bootloader-emmc-linux-176/dragonboard-410c-bootloader-emmc-linux-176.zip"
SHA256=a37c4e82a970ae2350fcfc7180559caf1dc3928e7c169316fe4ab899b7d305ad
FNAME=$(basename ${SRC})

TMPDIR=$(mktemp -d)
trap 'rm -rf --one-file-system -- "${TMPDIR:?}"' EXIT

mkdir -p out/fw

# extract Qualcom firmware
wget -P ${TMPDIR} ${SRC}

echo "${SHA256} ${TMPDIR}/${FNAME}" | sha256sum -c

unzip -o -j -d out/fw/ ${TMPDIR}/${FNAME} ${FNAME%.*}/rpm.mbn ${FNAME%.*}/sbl1.mbn ${FNAME%.*}/tz.mbn

